import re

def count_indent(line):
    return len(line) - len(line.lstrip(' '))

def parse_scalar(s):
    s = s.strip()
    if not s:
        return None
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]
    if s == 'true':
        return True
    if s == 'false':
        return False
    if s in ('null', '~', ''):
        return None
    try:
        if '.' not in s and 'e' not in s.lower():
            return int(s)
    except:
        pass
    try:
        return float(s)
    except:
        pass
    return s

def parse_block(lines, start, parent_indent):
    if start >= len(lines):
        return None, start
    first_line = lines[start]
    first_indent = count_indent(first_line)
    stripped = first_line.strip()
    if stripped.startswith('- '):
        lst = []
        i = start
        while i < len(lines):
            line = lines[i]
            indent = count_indent(line)
            if indent < first_indent:
                break
            if indent > first_indent:
                break
            stripped = line.strip()
            if not stripped.startswith('- '):
                break
            after_dash = stripped[2:].strip()
            if not after_dash:
                if i+1 < len(lines):
                    next_indent = count_indent(lines[i+1])
                    if next_indent > indent:
                        nested, next_i = parse_block(lines, i+1, indent)
                        lst.append(nested)
                        i = next_i
                        continue
                lst.append(None)
                i += 1
            else:
                if ': ' in after_dash or after_dash.endswith(':'):
                    map_lines = []
                    map_lines.append(' ' * (indent+2) + after_dash)
                    j = i+1
                    while j < len(lines):
                        nl = lines[j]
                        ni = count_indent(nl)
                        if ni <= indent:
                            break
                        map_lines.append(nl)
                        j += 1
                    nested_map, _ = parse_block(map_lines, 0, 0)
                    lst.append(nested_map)
                    i = j
                else:
                    lst.append(parse_scalar(after_dash))
                    i += 1
        return lst, i
    else:
        m = {}
        i = start
        while i < len(lines):
            line = lines[i]
            indent = count_indent(line)
            if indent < first_indent and i != start:
                break
            if indent > first_indent:
                break
            stripped = line.strip()
            if not stripped or stripped.startswith('- '):
                break
            if ':' not in stripped:
                i += 1
                continue
            key_part, value_part = stripped.split(':', 1)
            key = key_part.strip()
            value_str = value_part.strip()
            if not value_str:
                if i+1 < len(lines):
                    next_indent = count_indent(lines[i+1])
                    if next_indent > indent:
                        nested, next_i = parse_block(lines, i+1, indent+1)
                        m[key] = nested
                        i = next_i
                        continue
                m[key] = None
                i += 1
            else:
                m[key] = parse_scalar(value_str)
                i += 1
        return m, i

def parse_yaml_simple(text):
    docs = []
    current = []
    for line in text.splitlines():
        stripped = line.strip()
        if stripped == '---':
            if current:
                docs.append('\n'.join(current))
                current = []
            continue
        current.append(line)
    if current:
        docs.append('\n'.join(current))
    parsed = []
    for d in docs:
        if not d.strip():
            parsed.append(None)
            continue
        lines = [l for l in d.splitlines() if l.strip() and not l.strip().startswith('#')]
        if not lines:
            parsed.append(None)
            continue
        root, _ = parse_block(lines, 0, 0)
        parsed.append(root)
    return parsed

