# Let's try to implement expression evaluator for subset.

import re, json, os

def eval_path(data, path):
    # path like .a.b[0].c
    # returns list of values? Or single? Need to handle [] iteration.
    # We'll implement as returning list of results, and handle pipe.
    # For simplicity, support:
    # - . -> identity returns [data]
    # - .a -> property access
    # - .a.b -> nested
    # - [n] -> index
    # - [] -> iterate (expand)
    # So we need to parse path tokens.
    # Example: .a.b[0].c => tokens: property a, property b, index 0, property c
    # But with []: .a.b[] => property a, property b, iterate
    # For evaluation, we can iterate over current list of contexts.

    # We'll split by '.' but careful with brackets.
    # Approach: tokenize path string into steps.
    # Steps: each step is dict with maybe key and optional index operation.
    # We'll parse using regex.

    # Remove leading .
    if not path.startswith('.'):
        raise ValueError(f"path must start with .: {path}")
    if path == '.':
        return [data]

    # We need to handle sequence of operations like .a.b[0] etc.
    # We'll use regex to find components: either .key or [index] or [] or [key]?

    tokens = []
    i = 0
    # path includes leading .
    # We'll iterate character by character
    # Simplified: split by '.' but keep brackets
    # Actually .a.b[0].c => after split by '.' => ['', 'a', 'b[0]', 'c'] etc
    parts = path.split('.')
    # first part is '' because leading dot
    for part in parts:
        if part == '':
            continue
        # part may contain brackets: e.g., b[0], b[], b[0][1], etc
        # We need to extract base and bracket operations
        # Example: b[0] => base=b, brackets=[0]
        # b[] => base=b, brackets=[[]]
        # b[0].c will be separate part, so okay
        # For part like "a", base=a, no brackets
        # For part like "b[0]" base=b, brackets [0]
        # Use regex
        m = re.match(r'^([^\[\]]*)((?:\[[^\]]*\])*)$', part)
        if not m:
            raise ValueError(f"invalid path part: {part}")
        base = m.group(1)
        brackets_str = m.group(2)
        if base:
            tokens.append(('key', base))
        # parse brackets
        if brackets_str:
            # find all [..]
            for inner in re.findall(r'\[([^\]]*)\]', brackets_str):
                if inner == '':
                    tokens.append(('iter', None))
                else:
                    # try int
                    try:
                        idx = int(inner)
                        tokens.append(('index', idx))
                    except:
                        # could be string key? Or expression?
                        tokens.append(('index_str', inner))
    # Now evaluate tokens over data
    # Start with list containing data
    current = [data]
    for typ, val in tokens:
        next_current = []
        for ctx in current:
            if ctx is None:
                continue
            if typ == 'key':
                if isinstance(ctx, dict):
                    if val in ctx:
                        next_current.append(ctx[val])
                    else:
                        # missing key -> None? In yq, missing returns null and then for -e flag it errors?
                        # For generic, return None to indicate no value
                        next_current.append(None)
                elif isinstance(ctx, list):
                    # If ctx is list and we access key, maybe we should map over list? In yq, .a.b[] where b is list etc.
                    # For key access on list, if list contains dicts, you might want to get property of each?
                    # Actually in yq, .a.b[].c where .a.b is list, [] iterates, then .c accesses each element's c.
                    # Our iter token handles that. If we have .a.b.c and b is list, what should happen? In yq, .a.b.c where b is list would give null? Or maybe iterates? Let's check original behavior.
                    # Test: data {"a": {"b": [{"c":1},{"c":2}]}} ; .a.b.c should give null? Let's test with actual yq later, but for now assume if ctx is list, we need to apply key to each element and collect?
                    # Simplified: if ctx is list, apply key access to each element that is dict.
                    for item in ctx:
                        if isinstance(item, dict) and val in item:
                            next_current.append(item[val])
                else:
                    next_current.append(None)
            elif typ == 'index':
                if isinstance(ctx, list):
                    if 0 <= val < len(ctx):
                        next_current.append(ctx[val])
                    else:
                        next_current.append(None)
                else:
                    next_current.append(None)
            elif typ == 'iter':
                if isinstance(ctx, list):
                    next_current.extend(ctx)
                else:
                    # if not list, maybe nothing?
                    pass
            elif typ == 'index_str':
                # treat as string key inside brackets, e.g., ["key"] ?
                # For simplicity, treat as key
                if isinstance(ctx, dict) and val in ctx:
                    next_current.append(ctx[val])
                else:
                    next_current.append(None)
        current = next_current
    return current

