def eval_condition(data, cond_expr, context):
    # cond_expr like "di == 0" or ".a == 1" or "fi == 0"
    # We'll reuse eval_expr and check truthiness
    # For simple equality, we can eval left and right
    # Find operator
    ops = ['==', '!=', '<=', '>=', '<', '>']
    for op in ops:
        if op in cond_expr:
            parts = cond_expr.split(op, 1)
            if len(parts) == 2:
                lhs = parts[0].strip()
                rhs = parts[1].strip()
                lhs_res = eval_expr(data, lhs, context)
                rhs_res = eval_expr(data, rhs, context)
                lhs_val = lhs_res[0] if lhs_res else None
                rhs_val = rhs_res[0] if rhs_res else None
                # rhs_val may be literal int
                # Try parse rhs as literal if eval returned None
                if rhs_res == [None] or not rhs_res:
                    lit = eval_literal(rhs)
                    rhs_val = lit if lit is not None else rhs
                if op == '==':
                    return lhs_val == rhs_val
                elif op == '!=':
                    return lhs_val != rhs_val
                elif op == '<':
                    try:
                        return lhs_val < rhs_val
                    except:
                        return False
                elif op == '>':
                    try:
                        return lhs_val > rhs_val
                    except:
                        return False
                elif op == '<=':
                    try:
                        return lhs_val <= rhs_val
                    except:
                        return False
                elif op == '>=':
                    try:
                        return lhs_val >= rhs_val
                    except:
                        return False
    # If no operator, evaluate as truthiness
    res = eval_expr(data, cond_expr, context)
    if not res:
        return False
    val = res[0]
    if val is None or val is False:
        return False
    if val == [] or val == {}:
        return False
    return True

def eval_expr(data, expr, context):
    # Split by pipe
    parts = split_expression(expr)
    # For pipe, evaluate left, then for each result evaluate right
    if len(parts) > 1:
        # Start with [data]
        current = [data]
        for part in parts:
            next_current = []
            for ctx_data in current:
                # For each data, eval part with context
                # Need to copy context per iteration? Keep same reference for variable modifications?
                res = eval_expr_single(ctx_data, part, context)
                next_current.extend(res)
            current = next_current
        return current
    else:
        return eval_expr_single(data, expr, context)

