#!/usr/bin/env python3
import sys, os, json, re
from pathlib import Path

VERSION = "yq (https://github.com/mikefarah/yq/) version v4.52.5"

HELP_MAIN = open('/tmp/main_help.txt').read() if os.path.exists('/tmp/main_help.txt') else "yq help"
HELP_EVAL = open('/tmp/eval_help.txt').read() if os.path.exists('/tmp/eval_help.txt') else HELP_MAIN
HELP_EVALALL = open('/tmp/evalall_help.txt').read() if os.path.exists('/tmp/evalall_help.txt') else HELP_MAIN

def load_completion(shell):
    path_map = {
        'bash': '/tmp/bash_completion.bash',
        'zsh': '/tmp/zsh_completion.zsh',
        'fish': '/tmp/fish_completion.fish',
