def detect_format_from_ext(filename):
    if not filename or filename == '-':
        return 'auto'
    ext = Path(filename).suffix.lower()
    if ext in ('.yaml', '.yml'):
        return 'yaml'
    if ext == '.json':
        return 'json'
    if ext == '.xml':
        return 'xml'
    if ext == '.csv':
        return 'csv'
    if ext == '.tsv':
        return 'tsv'
    if ext in ('.props', '.properties'):
        return 'props'
    if ext == '.ini':
        return 'ini'
    if ext == '.toml':
        return 'toml'
    if ext == '.lua':
        return 'lua'
    if ext == '.hcl':
        return 'hcl'
    return 'auto'

