import re, json

def parse_path(path):
    if not path.startswith('.'):
        return None
    if path=='.':
        return []
    tokens=[]
    parts=path.split('.')
    for part in parts:
        if part=='':
            continue
        m=re.match(r'^([^\[\]]*)((?:\[[^\]]*\])*)$', part)
        if not m:
            continue
        base=m.group(1)
        brackets=m.group(2)
        if base:
            tokens.append(('key', base))
        if brackets:
            for inner in re.findall(r'\[([^\]]*)\]', brackets):
                if inner=='':
                    tokens.append(('iter', None))
                else:
                    try:
                        idx=int(inner)
                        tokens.append(('index', idx))
                    except:
                        tokens.append(('key', inner))
    return tokens

def eval_path(data, tokens):
    if not tokens:
        return [data]
    cur=[data]
    for typ,val in tokens:
        nxt=[]
        for ctx in cur:
            if ctx is None:
                nxt.append(None)
                continue
            if typ=='key':
                if isinstance(ctx, dict) and val in ctx:
                    nxt.append(ctx[val])
                else:
                    nxt.append(None)
            elif typ=='index':
                if isinstance(ctx, list) and 0 <= val < len(ctx):
                    nxt.append(ctx[val])
                else:
                    nxt.append(None)
            elif typ=='iter':
                if isinstance(ctx, list):
                    nxt.extend(ctx)
        cur=nxt
    return cur

