    if ext in ('.props', '.properties'):
        return 'props'
    if ext == '.ini':
        return 'ini'
    if ext == '.toml':
        return 'toml'
    if ext == '.lua':
        return 'lua'
    if ext == '.hcl':
        return 'hcl'
    return 'auto'

