        for ctx in cur:
            if ctx is None:
                nxt.append(None)
                continue
            if typ=='key':
                if isinstance(ctx, dict) and val in ctx:
                    nxt.append(ctx[val])
                elif isinstance(ctx, list):
                    for item in ctx:
                        if isinstance(item, dict) and val in item:
                            nxt.append(item[val])
