                        items[new_key]=v
            return items
        flat = flatten(data)
        return "\n".join(f"{k}{properties_separator}{v}" for k,v in flat.items()) + "\n"
    elif fmt in ('shell', 's'):
        def flatten(d, prefix=''):
            items={}
            if isinstance(d, dict):
                for k,v in d.items():
                    new_key = f"{prefix}{shell_sep}{k}" if prefix else k
                    if isinstance(v, dict):
                        items.update(flatten(v, new_key))
                    elif isinstance(v, list):
                        for i, elem in enumerate(v):
                            items.update(flatten(elem, f"{new_key}{shell_sep}{i}"))
                    else:
                        items[new_key]=v
            return items
        flat=flatten(data)
        return "\n".join(f"{k}={v}" for k,v in flat.items()) + "\n"
    elif fmt in ('lua', 'l'):
        def to_lua(d, lvl=0):
            ind = "\t"*lvl
            if isinstance(d, dict):
                if not d:
                    return "{}"
                lines=["{"]
                for k,v in d.items():
                    if isinstance(k, str) and re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', k) and lua_unquoted:
                        key_str=k
                    else:
                        key_str=f'["{k}"]'
                    val_str=to_lua(v, lvl+1)
                    lines.append(f"{ind}\t{key_str} = {val_str};")
                lines.append(f"{ind}}}")
                return "\n".join(lines)
            elif isinstance(d, list):
                if not d:
                    return "{}"
                lines=["{"]
                for elem in d:
                    lines.append(f"{ind}\t{to_lua(elem, lvl+1)},")
                lines.append(f"{ind}}}")
                return "\n".join(lines)
            elif isinstance(d, str):
                return f'"{d}"'
            elif isinstance(d, bool):
                return "true" if d else "false"
            elif d is None:
                return "nil"
            else:
                return str(d)
        lua_data=to_lua(data,0)
        if lua_globals:
            if isinstance(data, dict):
                out=""
                for k,v in data.items():
