def parse_path(path):
    if not path.startswith('.'):
        return None
    if path=='.':
        return []
    tokens=[]
    parts=path.split('.')
    for part in parts:
        if part=='':
            continue
        m=re.match(r'^([^\[\]]*)((?:\[[^\]]*\])*)$', part)
        if not m:
            continue
        base=m.group(1)
        brackets=m.group(2)
        if base:
            tokens.append(('key', base))
        if brackets:
            for inner in re.findall(r'\[([^\]]*)\]', brackets):
                if inner=='':
                    tokens.append(('iter', None))
                else:
                    try:
                        idx=int(inner)
                        tokens.append(('index', idx))
                    except:
                        tokens.append(('key', inner))
    return tokens

def eval_path(data, tokens):
    if not tokens:
        return [data]
    cur=[data]
    for typ,val in tokens:
        nxt=[]
        for ctx in cur:
            if ctx is None:
                nxt.append(None)
                continue
            if typ=='key':
                if isinstance(ctx, dict) and val in ctx:
                    nxt.append(ctx[val])
                else:
                    nxt.append(None)
            elif typ=='index':
                if isinstance(ctx, list) and 0 <= val < len(ctx):
                    nxt.append(ctx[val])
                else:
                    nxt.append(None)
            elif typ=='iter':
                if isinstance(ctx, list):
                    nxt.extend(ctx)
        cur=nxt
    return cur

def deep_merge(a,b):
    if isinstance(a, dict) and isinstance(b, dict):
        res=dict(a)
        for k,v in b.items():
            if k in res:
                res[k]=deep_merge(res[k], v)
            else:
                res[k]=v
        return res
    return b

def set_path(data, tokens, value):
    if not tokens:
        return value
    cur=data
    for i,(typ,val) in enumerate(tokens):
        is_last=i==len(tokens)-1
        if typ=='key':
            if is_last:
                if isinstance(cur, dict):
                    cur[val]=value
                return data
            else:
                if val not in cur or cur[val] is None:
                    cur[val]={}
                cur=cur[val]
        elif typ=='index':
            if not isinstance(cur, list):
                return data
            while len(cur) <= val:
                cur.append(None)
            if is_last:
                cur[val]=value
                return data
            else:
                if cur[val] is None:
                    cur[val]={}
                cur=cur[val]
    return data

def eval_literal(s):
    s=s.strip()
    if not s:
        return None
    if len(s)>=2 and ((s[0]=='"' and s[-1]=='"') or (s[0]=="'" and s[-1]=="'")):
        return s[1:-1]
    if s=='true':
        return True
    if s=='false':
        return False
    if s=='null':
        return None
    try:
        return int(s)
    except:
        pass
    try:
        return float(s)
    except:
        pass
    if (s.startswith('{') and s.endswith('}')) or (s.startswith('[') and s.endswith(']')):
        try:
            return json.loads(s)
        except:
            pass
    return None

def split_expression(expr):
    parts=[]
    cur=''
    in_single=False
    in_double=False
    paren=0
    bracket=0
    brace=0
    i=0
    while i < len(expr):
        c=expr[i]
        if c=="'" and not in_double:
            if i==0 or expr[i-1]!='\\':
                in_single=not in_single
            cur+=c
        elif c=='"' and not in_single:
            if i==0 or expr[i-1]!='\\':
                in_double=not in_double
            cur+=c
        elif not in_single and not in_double:
            if c=='(':
                paren+=1
                cur+=c
            elif c==')':
                paren-=1
                cur+=c
            elif c=='[':
                bracket+=1
                cur+=c
            elif c==']':
                bracket-=1
                cur+=c
            elif c=='{':
                brace+=1
                cur+=c
            elif c=='}':
                brace-=1
                cur+=c
            elif c=='|' and paren==0 and bracket==0 and brace==0:
                if i+1 < len(expr) and expr[i+1]=='=':
                    cur+=c
                else:
                    parts.append(cur.strip())
                    cur=''
            else:
                cur+=c
        else:
            cur+=c
        i+=1
    if cur.strip():
        parts.append(cur.strip())
    return parts

def find_top_level_op(expr_str, op):
    in_single=False
    in_double=False
    paren=0
    bracket=0
    brace=0
    i=0
    while i < len(expr_str):
        c=expr_str[i]
        if c=="'" and not in_double:
            if i==0 or expr_str[i-1]!='\\':
                in_single=not in_single
        elif c=='"' and not in_single:
            if i==0 or expr_str[i-1]!='\\':
                in_double=not in_double
        elif not in_single and not in_double:
            if c=='(':
                paren+=1
            elif c==')':
                paren-=1
            elif c=='[':
                bracket+=1
            elif c==']':
                bracket-=1
            elif c=='{':
                brace+=1
            elif c=='}':
                brace-=1
            elif paren==0 and bracket==0 and brace==0:
                if expr_str[i:i+len(op)]==op:
                    return i
        i+=1
    return -1

def eval_expr_single(data, expr, context):
    expr=expr.strip()
    if not expr:
        return [data]
    if re.match(r'^\$[a-zA-Z_][a-zA-Z0-9_]*$', expr):
        var_name=expr[1:]
        if var_name in context:
            return [context[var_name]]
        return [None]
    if expr.startswith('select('):
        depth=0
        in_single=False
        in_double=False
        end_idx=-1
        for i,ch in enumerate(expr):
            if ch=="'" and not in_double:
                if i==0 or expr[i-1]!='\\':
                    in_single=not in_single
            elif ch=='"' and not in_single:
                if i==0 or expr[i-1]!='\\':
                    in_double=not in_double
            elif not in_single and not in_double:
                if ch=='(':
                    depth+=1
                elif ch==')':
                    depth-=1
                    if depth==0:
                        end_idx=i
                        break
        if end_idx!=-1:
            after=expr[end_idx+1:].strip()
            if not after:
                inner=expr[7:end_idx].strip()
                if '==' in inner:
                    lhs,rhs=inner.split('==',1)
                    lhs=lhs.strip()
                    rhs=rhs.strip()
                    lhs_val=None
                    if lhs in ('fi','fileIndex'):
                        lhs_val=context.get('fi',0)
                    elif lhs in ('di','documentIndex'):
                        lhs_val=context.get('di',0)
                    else:
                        lhs_res=eval_expr(data, lhs, context)
                        lhs_val=lhs_res[0] if lhs_res else None
                    try:
                        rhs_val=int(rhs)
                    except:
                        rhs_val=eval_literal(rhs)
                    if lhs_val==rhs_val:
                        return [data]
                    else:
                        return []
                return [data]
    if expr=='keys':
        if isinstance(data, dict):
            return [list(data.keys())]
        return [None]
    if expr in ('fileIndex','fi'):
        return [context.get('fi',0)]
    if expr in ('documentIndex','di'):
        return [context.get('di',0)]
    if expr=='filename':
        return [context.get('filename','')]
    if expr.startswith('strenv('):
        if context.get('disable_env'):
            sys.stderr.write("Error: env operations have been disabled\n")
            sys.exit(1)
        inner=expr[7:-1].strip().strip('"').strip("'")
        return [os.getenv(inner,"")]
    if expr.startswith('load('):
        if context.get('disable_file'):
            sys.stderr.write("Error: file operations have been disabled\n")
            sys.exit(1)
        inner=expr[5:-1].strip().strip('"').strip("'")
        docs, _ = load_file_with_format(inner, False, 'auto')
        return [docs[0] if docs else None]
    if expr.startswith('collect('):
        all_docs=context.get('all_docs',[])
        return [all_docs]
    if expr.startswith('[') and expr.endswith(']'):
        inner=expr[1:-1].strip()
        if not inner:
            return [[]]
        res=eval_expr(data, inner, context)
        return [res]
    m=re.match(r'^(.*)\s+as\s+\$([a-zA-Z_]+)\s*$', expr)
    if m:
        lhs=m.group(1).strip()
        var_name=m.group(2)
        lhs_res=eval_expr(data, lhs, context)
        if lhs_res:
            context[var_name]=lhs_res[0]
        return lhs_res
    if 'ireduce' in expr:
        m=re.match(r'^(.*)\s+ireduce\s*\(\s*(.*)\s*;\s*(.*)\s*\)\s*$', expr)
        if m:
            left_part=m.group(1).strip()
            init_part=m.group(2).strip()
            reduce_part=m.group(3).strip()
            m2=re.match(r'^(.*)\s+as\s+\$([a-zA-Z_]+)\s*$', left_part)
            if m2:
                var_name=m2.group(2)
                all_docs=context.get('all_docs',[])
                init_val=eval_literal(init_part)
                if init_val is None:
                    if init_part=='{}':
                        init_val={}
                    elif init_part=='0':
                        init_val=0
                    else:
                        init_val={}
                acc=init_val
                for doc_item in all_docs:
                    new_ctx=dict(context)
                    new_ctx[var_name]=doc_item
                    res_list=eval_expr(acc, reduce_part, new_ctx)
                    if res_list:
                        acc=res_list[0]
                return [acc]
    for op in ('|=', '='):
        spaced_op = f' {op} '
        idx_spaced = find_top_level_op(expr, spaced_op)
        idx = idx_spaced
        found_op_len = len(spaced_op)
        if idx == -1:
            idx = find_top_level_op(expr, op)
            found_op_len = len(op)
        if idx!=-1:
            if op=='=' and (expr[idx:idx+2]=='==' or (idx>0 and expr[idx-1] in ('=', '!', '<', '>'))):
                continue
            if op=='=' and idx>0 and expr[idx-1] in ('|','+','-','*','/','%'):
                continue
            lhs=expr[:idx].strip()
            rhs=expr[idx+found_op_len:].strip()
            lhs_tokens=parse_path(lhs)
            rhs_res=eval_expr(data, rhs, context)
            rhs_val=rhs_res[0] if rhs_res else None
            if op=='|=':
                cur_vals=eval_path(data, lhs_tokens)
                cur=cur_vals[0] if cur_vals else None
                new_vals=eval_expr(cur, rhs, context)
                new_val=new_vals[0] if new_vals else None
                set_path(data, lhs_tokens, new_val)
                return [data]
            elif op=='=':
                set_path(data, lhs_tokens, rhs_val)
                return [data]
    for op in (' * ', ' + '):
        idx=find_top_level_op(expr, op)
        if idx!=-1:
            lhs=expr[:idx].strip()
            rhs=expr[idx+len(op):].strip()
            lhs_res=eval_expr(data, lhs, context)
            rhs_res=eval_expr(data, rhs, context)
            lv=lhs_res[0] if lhs_res else None
            rv=rhs_res[0] if rhs_res else None
            if op.strip()=='*':
                if isinstance(lv, dict) and isinstance(rv, dict):
                    return [deep_merge(lv, rv)]
                elif isinstance(lv, (int,float)) and isinstance(rv, (int,float)):
                    return [lv*rv]
            elif op.strip()=='+':
                if isinstance(lv, (int,float)) and isinstance(rv, (int,float)):
                    return [lv+rv]
                elif isinstance(lv, str) and isinstance(rv, str):
                    return [lv+rv]
                elif isinstance(lv, dict) and isinstance(rv, dict):
                    return [deep_merge(lv, rv)]
                elif isinstance(lv, str) or isinstance(rv, str):
                    return [str(lv)+str(rv)]
    lit=eval_literal(expr)
    if lit is not None or expr in ('null','true','false'):
        return [lit]
    tokens=parse_path(expr)
    if tokens is not None:
        return eval_path(data, tokens)
    sys.stderr.write(f"Error: bad expression: {expr}\n")
    sys.exit(1)

def eval_expr(data, expr, context=None):
    if context is None:
        context={}
    parts=split_expression(expr)
    if len(parts)>1:
        cur=[data]
        for part in parts:
            nxt=[]
            for d in cur:
                nxt.extend(eval_expr_single(d, part, context))
            cur=nxt
        return cur
    else:
        return eval_expr_single(data, expr, context)
